// Shape of TIME


let scale;
let t = 0;

// colors without alpha
const palettes = [
	["#4596c7", "#6d8370", "#e45240", "#21d3a4", "#3303f9"],
	["#b8dbcc", "#472433", "#e1fff6", "#e3b0c8", "#212523"],
	["#ffffff", "#292929", "#000000", "#f7fcfe", "#14001a"],
	["#5d565c", "#b41a1d", "#c0dee4", "#edb136", "#e07958"],
	["#add8e6", "#9fb7f4", "#12177d", "#9bb5e9", "#e4f2f7"],
	["#1b1b1b", "#292929", "#f3f3f3", "#222222", "#ff0000"],
	["#eda492", "#d59c95", "#af3918", "#d9b6b5", "#853532"],
	["#f86fcd", "#97d183", "#240ce8", "#b0e298", "#7f37e8"],
	["#2E294E", "#541388", "#F1E9DA", "#FFD400", "#D90368"],
	["#e9baaa", "#ffa07a", "#164555", "#ffe1d0", "#acd9e7"]
]

/** OPC START **/
OPC.slider('Central_Star', 500, 0, 1000, 10);
OPC.slider('Nebula_Rings', 50, 50, 100, 10);
OPC.slider('Star_Amount', 150, 50, 200, 10);
OPC.slider('Nebula_Color', palettes.length - 1, 0, palettes.length - 1, 1);
OPC.slider('Turbulence', 5, 2, 20, 1);
OPC.slider('Nebula_Size', 800, 500, 1000, 50);
OPC.slider('Stars_Size', 20, 5, 30, 1);
OPC.slider('Stars_Tail', 5, 1, 30, 1);
/** OPC END **/

let PCentral_Star = Central_Star;
let PNebula_Rings = Nebula_Rings;
let PStar_Amount = Star_Amount;
let PNebula_Color = Nebula_Color;
let PTurbulence = Turbulence;
let PNebula_Size = Nebula_Size;
let PStars_Tail = Stars_Tail;
let PStars_Size = Stars_Size;

function setup() {
	randomSeed(Central_Star);
	noiseSeed(Central_Star);
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	background(266, 50, 5, 100);
	noFill();
	scale = 1;
}

function draw() {
	randomSeed(Central_Star);
	noiseSeed(Central_Star);
	background(266, 50, 5, Stars_Tail);
	push();
	translate(random(width / 4 * 3, width / 4), random(height / 4 * 3, height / 4));


	for (let r = 0; r < Nebula_Size; r += Nebula_Size / Nebula_Rings) {
		stroke(random(palettes[Nebula_Color]));
		strokeCap(ROUND);
		let o_angle = random(TAU);
		rotate(o_angle + t);

		// blendMode(LIGHTEST);
		for (
			let a = -TAU / Star_Amount; a < TAU + TAU / Star_Amount; a += TAU / Star_Amount
		) {
			let x = r * cos(a);
			let y = r * sin(a);
			let n = map(noise(x * (Turbulence / 1000), y * (Turbulence / 1000)), 0, 1, -0, scale);
			stroke(random(palettes[Nebula_Color]));
			n = random(n / 1, n / 4);
			strokeWeight(random(0.1 * (Stars_Size - r / 100)));
			point(x * (1 + random(-n, n)), y * (1 + random(-n, n)));

		}
	}
	pop();
	t += TAU / 36000 / 5;
	change_opc();
}

function change_opc() {
	if (PCentral_Star != Central_Star ||
		PNebula_Rings != Nebula_Rings ||
		PStar_Amount != Star_Amount ||
		PNebula_Color != Nebula_Color ||
		PTurbulence != Turbulence ||
		PNebula_Size != Nebula_Size ||
		PStars_Tail != Stars_Tail ||
		PStars_Size != Stars_Size) {

		PCentral_Star = Central_Star;
		PNebula_Rings = Nebula_Rings;
		PStar_Amount = Star_Amount
		PNebula_Color = Nebula_Color;
		PTurbulence = Turbulence;
		PNebula_Size = Nebula_Size;
		PStars_Tail = Stars_Tail;
		PStars_Size = Stars_Size;

		randomSeed(Central_Star);
		noiseSeed(Central_Star);
		background(10);
	}
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("Shape of TIME_nebula", "png");
	}
}

